"""Chapter-owned content assembly; preserve deck order/IDs and patch specific SVGs."""
from pathlib import Path
import html
import re

root = Path(__file__).resolve().parents[2]
baseline = (root/'docs/reviews/ch16-ch17-ch18-baseline/ch18.html').read_text()
sections = re.findall(r'<section>.*?</section>', baseline, re.S)
figures = re.findall(r'<figure class="deck">.*?</figure>', baseline, re.S)


def bi(zh, en):
    return f'<div class="bilingual"><div class="lang-zh">{zh}</div><div class="lang-en">{en}</div></div>'


def title(zh, en, level=2):
    return f'<h{level}><span class="lang-zh">{zh}</span> <span class="lang-en">{en}</span></h{level}>'


def section(zh, en, body):
    return '<section>\n'+title(zh, en)+'\n'+body+'\n</section>'


def code(filename, label):
    value = (root/'examples/ch18'/filename).read_text().rstrip('\n')
    return f'<pre data-language="Pseudocode · {label}" data-kind="pseudocode" data-source="{filename}"><code>{html.escape(value)}</code></pre>'


def details(zh, en, body):
    return '<details><summary><span class="lang-zh">'+zh+'</span> <span class="lang-en">'+en+'</span></summary>'+body+'</details>'


# Keep original diagrams and fix only proven path syntax and necessary semantics.
figures[0] = figures[0].replace('M270 256 L270 328 Q270 336 262 336 L88 336 Q80 336 80 328 L80 219 Q80 219 NaN NaN L80 219', 'M230 219 L80 219')
figures[3] = figures[3].replace('L790 70 Q790 70 NaN NaN L790 70', 'L790 70')
figures[3] = figures[3].replace('Stripe 的幂等文档说明同键会重放首次结果 [3]', 'Stripe API v1 在执行开始后按同键重放保存结果 [3]')
figures[3] = figures[3].replace('Stripe replays the first result for a key [3]', 'Stripe API v1 replays the saved result after execution begins [3]')
figures[3] = figures[3].replace('Order API persists canonical evidence in Primary; Primary replies durably to Order API.', 'Order API persists a complete verified inbox event in Primary; Primary replies durably to Order API. A worker then applies canonical evidence.')
figures[3] = figures[3].replace('attempt / result', 'attempt / inbox').replace('2xx after durable handling', '2xx after durable inbox')
figures[3] = figures[3].replace('最后一笔只画回调恢复：PSP 请求 API，API 在 Primary 持久处理后才 2xx 回 PSP。恢复的是同一尝试。主动查单是另一种发现证据的办法，正文单独讲，不能混成这条绿色确认。', '回调先验签、完整落 PaymentInbox 后才 2xx。worker 再查渠道事实并推进同一尝试；主动查单走相同核验。绿色箭头确认的是已持久接收，不是已经发货。')
figures[3] = figures[3].replace('The final stroke shows webhook recovery only: PSP requests Order API; API acknowledges PSP with 2xx after durable inbox in Primary. It resolves the same attempt. Active queries are another evidence-discovery path, discussed separately in the text.', 'Verify the callback and commit the complete PaymentInbox before 2xx. A worker retrieves canonical evidence and resolves the same attempt. Active queries use the same validation. Green acknowledges durable receipt, not shipping completion.')

intro = section('先抓住三个决定', 'Three decisions to carry through the chapter', bi(
    '<ol><li><strong>提交边界：</strong>同用户请求键、原始回执、订单、库存归属与 outbox 一次提交。</li><li><strong>终结归属：</strong>付款与关单争同一订单行，只有本单 HELD 预留能改库存。</li><li><strong>钱与任务：</strong>超时保留未知；每笔真实收款都有履约、退款或人工核对责任，事件重复也不能吞任务。</li></ol>',
    '<ol><li><strong>Commit boundary:</strong> the scoped request key, creation receipt, order, owned stock holds and outbox commit together.</li><li><strong>Finalization:</strong> payment and close arbitrate on one order row; only that order’s HELD reservations change stock.</li><li><strong>Money and work:</strong> timeouts stay unknown. Every real capture has fulfillment, refund or review responsibility; duplicate events must not swallow work.</li></ol>'))

assumption_table = re.search(r'<table>.*?</table>', sections[1], re.S).group()
scope = section('需求与边界：先选择一个能讲完整的事务', 'Scope: begin with a transaction you can explain completely', bi(
    '<p>设计普通电商、单地域、单仓的多 SKU 购物篮，订单和库存共用关系库。提交成功即进入 <code>pending_pay</code>，表示整篮货已留好；15 分钟未付可尝试关单。浏览器跳回不是付款证据，支付渠道与本地库没有共同事务。售后、账本和配送分别见 Ch24、Ch27。</p><p>三条不变量：<strong>available≥0；每份预留只终结一次；每单只接受一笔收款用于履约</strong>。如果真实收到第二笔钱，仍须记录并退款；关闭后迟到收款也不复活订单。退款申请是待兑现的责任，不能显示为钱已到账。</p>',
    '<p>Use ordinary commerce, one region and one warehouse, with a multi-SKU basket and one relational database for orders and stock. A committed <code>pending_pay</code> order already owns its entire basket. After 15 minutes, closing may be attempted. Browser redirects do not prove payment, and the provider shares no database transaction. Ch24 and Ch27 expand after-sales, ledgers and delivery.</p><p>Three invariants: <strong>available≥0; each hold finalizes once; each order accepts one capture for fulfillment</strong>. A real second capture still needs a record and refund. Late money never revives a closed order. A refund request is an outstanding obligation, not proof that money reached the customer.</p>')+details('容量假设 A1–A12：全部是教学输入', 'Capacity assumptions A1–A12: teaching inputs', assumption_table+bi(
    '<p>一天 86,400 秒；容量用十进制 KB/GB/TB；三份包含主份。平均 1,000,000÷86,400=11.57 单/s，峰值 ×10≈116 单/s；成功付款约 81/s，重复通知约 162/s，到期关单约 35/s。三类入口合计约313次/s，仅是预算，不能证明数据库能力。峰值系数不再乘全年量。</p><p>单头、明细、索引共4 KB，则4 GB/天、1.46 TB/年、三份4.38 TB，日志备份另算。读缓存可服务旧的订单列表，预扣只能由权威主库裁决；故障切换若可能丢失已确认提交，必须另行说明持久化与复制承诺。</p>',
    '<p>Use 86,400 seconds/day, decimal KB/GB/TB, and three total copies including primary. Average creation is 1,000,000/86,400=11.57/s; 10× peak is about 116/s. Payment is about 81/s, duplicate notifications 162/s and expiry 35/s: roughly 313 entry attempts/s. These budget inputs do not prove database capacity. Do not multiply annual volume by the peak factor.</p><p>At 4 KB for header, items and indexes, storage is 4 GB/day, 1.46 TB/year or 4.38 TB for three copies, excluding logs and backups. Caches may serve stale order lists; only the authoritative primary acquires stock. If failover can lose acknowledged commits, state the separate durability and replication contract.</p>')))

checkout = section('同库下单：身份、库存与结果一起提交', 'Checkout: identity, stock and result share one commit', figures[0]+bi(
    '<p><code>POST /orders</code> 的身份是非空 <code>(user_id, request_key)</code>。输入绑定不可变报价 <code>quote_id</code>、币种、地址版本和按 SKU 规范排序的数量；摘要还包含认证用户。同键同摘要重放<strong>原始创建回执</strong>，异摘要409。报价由服务端给价并绑定用户；新单校验有效期、币种、明细和金额溢出，不能让客户端改价格。之后查实时订单状态使用 GET。</p>',
    '<p><code>POST /orders</code> uses a non-null <code>(user_id, request_key)</code>. Intent binds an immutable quote, currency, address version and canonically sorted SKU quantities, with the authenticated user in its digest. Equal intent replays the <strong>original creation receipt</strong>; changed intent returns 409. A server-owned quote binds the user. New checkout validates expiry, currency, items and amount overflow, never client prices. GET retrieves current order state.</p>')+code('checkout.pseudo','checkout identity and stock')+bi(
    '<p>唯一约束在数据库裁决并发；<code>ON CONFLICT DO NOTHING</code> 后用<strong>新语句</strong>回读已提交赢家，不能在原快照里猜它不存在。PostgreSQL 18 的 Read Committed 支持这一语义 [1]；身份字段必须非空 [2]。请求行中间的空回执不单独提交：库存、订单、明细、预留、事件或回执任一步失败都整笔回滚。缺货拒绝不保留成功身份，稍后重试可能成功；这是本例明确选择。</p><p>多个 SKU 按相同顺序更新；终结路径也按此顺序拿库存锁，死锁或序列化失败重试整笔事务 [8]。提交后回包丢失，仍用原键回读原单，不能换键再占一份货。成功回执不依赖消息已送达，更不依赖支付网络调用。</p>',
    '<p>Database uniqueness arbitrates concurrent requests. After <code>ON CONFLICT DO NOTHING</code>, use a <strong>new statement</strong> to read the committed winner; do not infer absence from the insertion snapshot. PostgreSQL 18 Read Committed supports this distinction [1], with non-null identities [2]. A partially built request with an empty receipt never commits separately. Any failure rolls back stock, order, items, holds, event and receipt. This model persists successful identities only, so a rejected out-of-stock request may succeed on a later retry.</p><p>Every basket and finalization path locks stock in the same SKU order; deadlock or serialization failure retries the whole transaction [8]. A lost commit reply reuses the original key and recovers the same order. A successful receipt does not depend on broker delivery or a provider call.</p>'))

state = section('订单状态：合法边拥有对应副作用', 'Order state: legal edges own their side effects', figures[1]+bi(
    '<p>同库事务消掉了独立可见的 <code>created</code> 半成品，成功直接待付。主路径是 <code>pending_pay → paid → shipped</code>；取消/到期只从 pending 进入 cancelled/closed。支付消费预留，关单释放预留，发货不再扣一次。已支付取消走售后，退钱和重新入库不是同一动作。</p><p>本章代码统一先锁订单行到提交，再核验当前状态；条件 UPDATE 仍检查影响行数。所有付款、取消、到期写手共用这个顺序。PG18 在已定位行发生并发更新后会重新检查 WHERE [1]，但它不会自动替你维护跨行的订单/预留/库存关系。履约通知携带版本；低版本事件不能覆盖新状态，外部仓库回执才准许 paid→shipped。</p>',
    '<p>The local transaction removes a separately visible half-created state. The committed path is <code>pending_pay → paid → shipped</code>. Cancellation and expiry leave pending for cancelled or closed. Payment consumes holds; closing releases them; shipping never decrements stock again. Paid cancellation is after-sales, and refunding money is distinct from restocking goods.</p><p>All code locks the order row until commit, checks its current state and checks affected rows on guarded updates. Payment, cancellation and expiry use that order. PG18 re-evaluates WHERE on a concurrently updated known row [1], but does not maintain cross-row order/hold/stock relations automatically. Fulfillment events carry versions; old events cannot overwrite new state. A warehouse completion receipt permits paid→shipped.</p>'))

inventory = section('库存：聚合计数之外，必须保存每单归属', 'Inventory: persist ownership beyond aggregate counters', figures[2]+bi(
    '<p>选择下单预留，因为付款前已承诺整篮数量。A9 从 A=10、R=0、S=0 开始，预留3件变7,3,0；付款变7,0,3，释放变10,0,0。A+R+S=10只适用无补货/退货的教学窗口。付款再扣也能用条件更新防负数，但收了钱可能无货，需要退款；它是另一份业务承诺。</p>',
    '<p>Reserve at checkout because payment entry already promises the whole basket. A9 starts at A=10,R=0,S=0; holding three gives 7,3,0, payment 7,0,3 and release 10,0,0. A+R+S=10 applies only without restock or returns. Guarded stock deduction at payment can prevent negative counters, but captured money may find no goods and need a refund: a different promise.</p>')+code('holds.pseudo','owned holds and closing')+bi(
    '<p><strong>反例：</strong>42号订单已释放，43号还预留3件，聚合 reserved≥3仍为真。再释放42会把43的货还给别人。因此预留主键为 <code>(order_id,sku_id)</code>、数量为正、状态只许 HELD→COMMITTED/RELEASED。<code>finish_holds_locked</code>不是新的事务：它在调用者已锁订单的事务内核对完整明细、更新库存、转换本单预留；任何缺行/零行/异常都回滚调用者全部写入。</p>',
    '<p><strong>Counterexample:</strong> order 42 released its units while 43 still holds three. Aggregate reserved≥3 remains true; releasing 42 again returns 43’s goods. Reservations therefore have primary key <code>(order_id,sku_id)</code>, positive quantities and only HELD→COMMITTED/RELEASED. <code>finish_holds_locked</code> opens no transaction: inside its caller’s order lock, it validates the full persisted basket, changes counters and transitions its own holds. Any missing row, zero-row update or exception rolls back all caller writes.</p>')+details('热点容量：为何全站百级下单仍会排队', 'Hot-row capacity: modest aggregate traffic can still queue', bi(
    '<p>A11假设一行每次持锁5 ms，串行理论上限1÷0.005=200次修改/s，未留排队余量。若峰值都打同一SKU，116次预留+约116次终结≈232次/s，已超过假设上限。先缩短事务、限制热门SKU和未付占用；分桶或拆库存需要重新定义分配与事务边界，不能只改图。</p>',
    '<p>A11 assumes 5 ms per locked-row mutation: 1/0.005=200/s theoretically, before queueing headroom. If peak demand hits one SKU, 116 reservations plus roughly 116 finalizations total 232/s, beyond that assumed limit. Shorten transactions and limit hot-SKU admission and unpaid occupancy first. Bucketing or splitting inventory requires changing allocation and transaction boundaries.</p>')))

payment = section('支付：先保留未知，再把每笔钱分配责任', 'Payment: preserve uncertainty, then assign every capture an obligation', figures[3]+bi(
    '<p>分别保存下单键、商户 <code>attempt_id</code>、通知 <code>event_id</code>、真实 <code>capture_id</code>。收款按渠道/商户账户作用域唯一，测试与生产环境隔离；同一收款多个事件不多发货，另一笔收款也不能按 order_id 去重丢掉。</p><p>新尝试必须在订单行锁内通过门槛：当前订单待付且未到期，旧尝试不存在，或渠道已确认<strong>不可再收款的 NO_CAPTURE 终态</strong>。PREPARED、处理中、需要用户操作、UNKNOWN和OBSERVED_REVIEW都挡新尝试。2秒等待上限、5秒首次查询、15分钟关单都不构成该终态 [5]。</p>',
    '<p>Keep separate checkout keys, merchant <code>attempt_id</code>, notification <code>event_id</code> and real <code>capture_id</code>. Captures are unique within provider and merchant-account scope; test and production are isolated. Multiple events for one capture never ship twice, while another real capture cannot disappear under order-ID deduplication.</p><p>A new attempt passes a gate under the order lock: the order is pending and unexpired, and no previous attempt exists or the provider confirmed an <strong>irreversible NO_CAPTURE terminal state</strong>. PREPARED, processing, customer action, UNKNOWN and OBSERVED_REVIEW all block a new attempt. A 2-second wait, 5-second first query or 15-minute close proves no such terminal state [5].</p>')+code('attempt.pseudo','attempt gate and unknown results')+bi(
    '<p>外调前保存稳定键和不可变参数。已知渠道对象就查同一对象；首次创建回包丢失、对象ID还未知时，只在渠道键仍保留的窗口内原键原参数重试，超窗保留UNKNOWN并对账，不盲建。Stripe <strong>API v1</strong> 在端点开始执行后保存首个状态/响应（包括500），相同参数重放，键至少24小时后可清理；API v2语义不同，不能泛称所有Stripe接口都如此 [3][5]。本地记录不按这个窗口删除。</p><p>入口先用官方SDK对<strong>原始请求体、签名、时间戳</strong>验真，检查配置的账户、环境与允许事件类型 [4]，完整事件持久落PaymentInbox才2xx。worker用该账户凭据查确切渠道对象，只接受已capture事实，授权/处理中不准发货。金额、币种、服务端设置的attempt标记、用户归属都与本地不可变尝试匹配，不能信浏览器或客户可改metadata。</p>',
    '<p>Persist the stable key and immutable parameters before calling out. Query the same known provider object. If object creation lost its reply and no ID is known, retry identical parameters/key only within retention; beyond it, retain UNKNOWN and reconcile rather than create blindly. Stripe <strong>API v1</strong> saves the first status/body after execution starts, including 500, replays identical requests and permits pruning after at least 24 hours. API v2 differs, so this is not a universal Stripe guarantee [3][5]. Local identities outlive that window.</p><p>Ingress uses the official SDK to verify the <strong>raw body, signature and timestamp</strong>, checks configured account/environment and allowlisted event types [4], then durably stores the complete PaymentInbox before 2xx. Workers retrieve the exact provider object with that account’s credentials and require captured evidence; authorization or processing cannot ship. Amount, currency, server-set attempt marker and owner must match immutable local intent. Browser fields or customer-editable metadata are insufficient.</p>')+code('capture.pseudo','capture ownership and refund obligations')+bi(
    '<p>渠道对象ID初始可空。创建响应或首个经渠道查询的事件，核对服务端专用attempt标记、账户/环境、金额/币种、归属后，在同一订单锁内<strong>只绑定一次</strong>；后续换对象进REVIEW。这个标记只能由支付后端设置，客户端不能修改。找不到本地尝试、字段不符、额外收款分别留下核对或退款责任，不发货。REVIEW把尝试置OBSERVED_REVIEW，只表示观察到待核对资金，绝非支付许可。</p><p>Capture唯一竞争后回读完整赢家；同一真实收款的不同event只复用已提交责任。已有capture的不可变字段冲突时，保留完整inbox待处理并告警，不能标DONE吞证据。正常关单冲突选择REFUND_DUE而不回滚收款；真正SQL/不变量异常则整笔回滚，inbox保留READY重试。退款按<strong>每笔capture</strong>唯一，用固定退款操作ID兑现；原收款记录不被删除 [7]。</p>',
    '<p>The provider object ID may initially be absent. A create response or first authenticated queried event validates a payment-backend-only attempt marker, account/environment, amount/currency and ownership, then <strong>binds once</strong> under the order lock. A later different object enters REVIEW. Clients cannot edit the trusted marker. Missing attempts, mismatches and extra captures leave review or refund obligations and never ship. OBSERVED_REVIEW means money needs investigation, not payment authorization.</p><p>After capture uniqueness arbitration, read the complete winner. Different events for one capture reuse its durable obligation. Conflicting immutable fields preserve the complete inbox as pending and alert instead of marking DONE. An expected close conflict selects REFUND_DUE without discarding capture evidence; a real SQL/invariant failure rolls back the transaction and leaves inbox READY. Refund obligations are unique <strong>per capture</strong> and use a stable refund operation ID. Never delete the original money fact [7].</p>'))

closing = section('关单：到期只负责触发，提交顺序决定结局', 'Closing: expiry triggers attempts; commit order decides the outcome', figures[4]+bi(
    '<p><strong>付款先提交：</strong>paid+本单COMMITTED+履约outbox，之后关单零行、不还货。<strong>关单先提交：</strong>closed+本单RELEASED，迟到capture写收款+RefundDue+退款outbox，绝不抢回库存或复活。paid/shipped后又发现另一capture也走退款；这笔钱的归属不能被已有履约结果覆盖。</p><p>本章选「到期时UNKNOWN也可先关单，迟到钱退款」政策。它牺牲一部分付款体验换库存可回收；本地闹钟不会撤销渠道已经发生的收款。延期保留到查清是另一种政策，需要更多占货预算。</p>',
    '<p><strong>Payment commits first:</strong> paid, owned COMMITTED holds and fulfillment outbox; later close changes nothing and returns no units. <strong>Close commits first:</strong> closed and owned RELEASED holds; a late capture commits capture evidence, RefundDue and refund outbox, never reacquiring stock or reviving. A second real capture after paid/shipped also needs a refund and cannot be overwritten by the existing fulfillment outcome.</p><p>We choose to allow closing while payment remains UNKNOWN, then refund late money. This trades some payment experience for reclaimable stock. A local timer never reverses a provider capture. Keeping stock until uncertainty resolves is another policy with a larger occupancy budget.</p>')+code('scan.pseudo','recoverable expiry scan')+bi(
    '<p>创建时用服务端时间设置expire_at，关单事务比数据库时间，不信浏览器倒计时。延迟消息是低延迟提示，扫描是兜底；索引 <code>(status,expire_at,order_id)</code>。每轮固定cutoff、连续按元组游标扫描，每单独立事务；失败仍保留pending+到期时间。下一轮<strong>从最老到期行重启</strong>，不能永久沿游标越过失败单。扫描读到pending后即使付款先赢，锁内复核也不会释放。</p>',
    '<p>Set expire_at from server time at creation and compare database time when closing, never the browser countdown. Delayed messages reduce latency; scans provide recovery with index <code>(status,expire_at,order_id)</code>. Fix a cutoff per round, paginate by tuple and use one transaction per order. Failed work remains pending and expired. The next round <strong>restarts at the oldest due row</strong>, rather than permanently skipping failures. Payment may win after scan selection; the locked recheck still prevents release.</p>')+details('扫描吞吐与预留上界：批大小不是恢复能力', 'Scan throughput and occupancy: batch size is not recovery capacity', bi(
    '<p>A7每60秒启动一轮，每批≤500但连续分页；所有扫描/延迟消息共享100尝试/s预算。单事务均值20ms时，至少2在途才支持这个尝试上限；净有效完成70单/s仍是待压测目标。峰值约35到期/s，一分钟新增2,100，至少5批；健康积压2,100÷70≈30秒处理，最老到期年龄目标≤120秒，包含发现与重试。</p><p>停扫10分钟有35×600=21,000积压；恢复时仍新到35/s，净追赶70−35=35/s，需600秒。A4峰值持续15分钟且全未付，约116×900=104,400份预留；每单3件则313,200件，是保守上界，货不够会先拒单。年龄超预算要告警、限制新预留，不能提前没收合法承诺。</p>',
    '<p>A7 starts a round every 60 seconds, continuously pages ≤500 and shares a 100-attempt/s budget across scanners and delayed-message workers. Mean transaction time 20 ms needs at least two in flight for that ceiling; 70 valid completions/s remains a load-test target. At 35 expiries/s, a minute adds 2,100 orders, at least five batches. A healthy minute’s backlog takes 2,100/70≈30 s; oldest due age targets ≤120 s including discovery and retry.</p><p>A ten-minute outage leaves 35×600=21,000 orders. Continued arrivals make net recovery 70−35=35/s, taking 600 seconds. A4 bounds a sustained unpaid fifteen-minute peak at 116×900=104,400 holds, or 313,200 units for three-unit baskets. Actual shortages reject sooner. Alert and restrict new holds when age exceeds budget; do not revoke valid promises early.</p>')))

delivery = section('Outbox与Inbox：事件身份和待办必须同时落地', 'Outbox and inbox: identity and durable work must co-commit', figures[5]+bi(
    '<p>本地outbox和订单状态一起提交，relay只读已提交行，broker持久确认后才标sent。发送成功但标记前崩溃仍会重复，outbox消掉的是双写漏发窗口 [6]。sent只说明broker接受，不能说明仓库已发货；分别监控未发outbox、PaymentInbox、队列、履约/退款任务的最老年龄。</p>',
    '<p>Local outbox and order state commit together. Relay reads committed rows and marks sent only after a durable broker acknowledgement. A crash after sending but before marking still duplicates publication; outbox removes the dual-write loss window [6]. Sent means broker acceptance, not shipment. Monitor oldest unpublished outbox, PaymentInbox, queue, fulfillment and refund work separately.</p>')+code('delivery.pseudo','durable ingress, relay and downstream jobs')+bi(
    '<p>消费端在自己的FulfillmentDB事务里插入 <code>(consumer,event_id)</code> 和按order唯一的履约Job；提交后才ACK。只写event_id不写任务会吞工作，先外部发货再记inbox会重复。此处仅保证<strong>一个持久履约任务</strong>，真正仓库RPC仍需稳定shipment_id、未知结果查询、持久重试；退款同样需要固定操作ID和终态证据。inbox提交失败全部回滚，已存在身份才意味着之前的任务一起提交。</p><p>PaymentInbox接收和收款应用分成两个事务是有意的：前者完整保存输入，后者原子决定收款责任；两次提交之间worker崩溃可重放capture。未知收款先查渠道、身份冲突保留并告警、字段不符进入人工核对；不能达到重试上限就删记录。</p>',
    '<p>Within its own FulfillmentDB transaction, the consumer inserts <code>(consumer,event_id)</code> and an order-unique Job, then acknowledges. An event ID alone can swallow work; shipping before recording inbox can repeat it. The promise is <strong>one durable fulfillment task</strong>. A real warehouse RPC still needs stable shipment_id, unknown-result queries and durable retries. Refunds likewise need stable operation IDs and terminal evidence. Inbox transaction failure rolls back everything; an existing identity means its job co-committed.</p><p>PaymentInbox ingress and capture application deliberately use separate transactions: the first preserves full input, the second atomically assigns money responsibility. A worker crash between them replays the same capture. Query unknown money, retain and alert on identity conflicts, review mismatches and preserve obligations beyond exhausted retry limits.</p>')+details('事件容量与何时拆库存服务', 'Event capacity and when inventory becomes a service', bi(
    '<p>A8保守按10事件/单，峰值116×10=1,160/s。停120秒积139,200；恢复2,000/s且新到继续，净840/s，约166秒排空，最老受影响任务可等约286秒。A12每日10M×1KB≈10GB，完成保留7天、三份≈210GB；未完成任务不按年龄删除，完成身份保留期覆盖支持的重放窗口。</p><p>多仓或独立库存所有权迫使拆库时，先creating，同库写预留命令outbox；库存按order身份确认后才pending_pay。取消意图持久保存，晚到预留必须释放。每步只有本地事务，补偿可能失败且必须可恢复 [7]。不能把Saga当全球回滚；不接受窗口就保留同库或明确协调事务的阻塞代价。</p>',
    '<p>A8 budgets 10 events/order: 116×10=1,160/s. A 120-second outage accumulates 139,200. Recovery at 2,000/s leaves net 840/s after continued arrivals, about 166 seconds to drain; oldest affected work may wait about 286 seconds. A12 gives 10M×1KB≈10GB/day, seven completed days and three copies≈210GB. Unfinished work cannot age out; completed identity retention covers the supported replay window.</p><p>If multiple warehouses or independent ownership force separate stores, begin in creating and locally commit a reservation command outbox. Only an inventory confirmation permits pending_pay. Persist cancellation intent and release late successful holds. Each step has a local transaction; compensation can fail and must resume [7]. Saga supplies no global rollback. Keep the shared store or explain coordination’s blocking costs when that window is unacceptable.</p>')))

recap = section('面试复盘：沿四个故障窗口口述', 'Interview review: walk four failure windows', bi(
    '<ol><li><strong>下单回包丢：</strong>原用户/键/摘要回读原创建结果，库存只留一次。</li><li><strong>付款结果未知：</strong>复用原尝试；新尝试只接受渠道确定的不可再收款终态。</li><li><strong>付款撞关单/第二笔钱：</strong>同一订单锁裁决，预留只终结一次；每笔capture有履约、退款或核对责任。</li><li><strong>事件投递重复：</strong>outbox可重复，完整inbox与持久任务接住崩溃；外部副作用继续用稳定身份恢复。</li></ol><p>对账核对渠道成功但本地未处理、paid但预留未消费、closed但退款未完成。发现异常生成带身份的修复任务，不批量无条件SET paid。继续阅读：<a href="ch21.html">Ch21库存抢购</a>、<a href="ch24.html">Ch24支付账本</a>、<a href="ch41.html">Ch41事务与消息</a>。</p>',
    '<ol><li><strong>Lost checkout reply:</strong> recover the original creation result with user/key/digest, never another hold.</li><li><strong>Unknown payment:</strong> retain the attempt; a new one requires provider-confirmed irreversible no-capture evidence.</li><li><strong>Payment races close or another capture:</strong> one order lock arbitrates, holds finalize once, and every capture has fulfillment, refund or review responsibility.</li><li><strong>Duplicate publication:</strong> outbox may repeat; complete inboxes and durable jobs survive crashes. External effects still recover through stable identities.</li></ol><p>Reconcile provider success not locally processed, paid without consumed holds and closed with unfinished refunds. Create identified repair tasks, never unconditional bulk SET paid. Continue with <a href="ch21.html">Ch21 inventory</a>, <a href="ch24.html">Ch24 payments and ledgers</a>, and <a href="ch41.html">Ch41 transactions and messaging</a>.</p>'))

refs = sections[9].replace('2026-10-04', '2026-10-23').replace('核对首次结果重放、同键参数一致和至少 24 小时后可清理', '核对 API v1 执行开始后保存首结果、同键参数一致和至少24小时后可清理；不套用 API v2').replace('Verified first-result replay, parameter matching, and eligibility for pruning after at least 24 hours', 'Verified API v1 result replay after execution starts, parameter matching and pruning after at least 24 hours; API v2 differs')
refs = refs.replace('</ol>', '<li id="ref8">[8] PostgreSQL Global Development Group, <a href="https://www.postgresql.org/docs/18/explicit-locking.html"><em>PostgreSQL 18: Explicit Locking</em></a>. <span class="lang-zh">2026-10-23核验；多对象固定锁序减少死锁，死锁可使整笔事务中止并需重试。</span> <span class="lang-en">Checked 2026-10-23: consistent object lock order avoids deadlocks; aborted transactions must be retried.</span></li></ol>')

cards = [
 ('回包丢了，原键返回什么？','What does same-key retry return after a lost reply?','原创建回执；先比认证用户和意图摘要，异意图409。实时状态另查GET。','The original creation receipt after user/intent matching; changed intent is 409. GET current state separately.'),
 ('第二个SKU缺货，先占的货呢？','What if the second SKU is unavailable?','请求身份、订单、明细、全部预留/库存和outbox整笔回滚。','Roll back request identity, order, items, every hold/counter and outbox together.'),
 ('reserved≥q为什么不够？','Why is reserved≥q insufficient?','总数可能属于另一单；本单HELD改态与计数必须同事务。','The aggregate may belong to another order. This hold’s HELD transition and counters co-commit.'),
 ('持有3件的两个结局？','Two outcomes for a three-unit hold?','7,3,0付款变7,0,3，释放变10,0,0；本单只走一条终结边。','7,3,0 becomes 7,0,3 on payment or 10,0,0 on release; one terminal edge wins.'),
 ('何时允许下一次付款尝试？','When may another payment attempt start?','订单仍待付未过期，且旧尝试不存在或渠道确认不可再收款的NO_CAPTURE终态。','The order is pending/unexpired, and no old attempt exists or its irreversible NO_CAPTURE terminal state is confirmed.'),
 ('UNKNOWN遇到15分钟怎么办？','What happens to UNKNOWN at fifteen minutes?','本例允许关单释放；迟到收款退款。时间经过不是付款失败证据。','This policy may close/release and refund late money. Elapsed time does not prove payment failure.'),
 ('首次对象ID未知，回调能恢复吗？','Can a callback recover an unknown first object ID?','验签并查渠道；服务端attempt标记、账户环境/金额币种/归属匹配后，订单锁内只绑定一次。','Verify/query the provider; validate server-only marker, account/environment, amount/currency and ownership, then bind once under the order lock.'),
 ('同capture两个event，另一capture呢？','Two events for one capture, then a different capture?','同capture复用已持久责任；新capture单独记录。每单只履约一次，多收款按capture退款。','One capture reuses its durable obligation. Record another separately; fulfill once and refund excess per capture.'),
 ('金额不符且确实收到了钱？','Money arrived with the wrong amount?','不发货；完整证据进REVIEW及持久核对任务，OBSERVED_REVIEW继续阻止新尝试。','Do not ship. Persist REVIEW evidence and work; OBSERVED_REVIEW still blocks a new attempt.'),
 ('关单与付款谁先赢？','Who wins payment versus close?','订单行锁裁决：付款先不还货，关单先不复活且记录退款责任。','The order lock arbitrates: paid first returns nothing; close first never revives and owes a refund.'),
 ('扫描游标越过失败行怎么办？','What if a scan cursor passes a failed row?','失败保留pending+expire_at；下一轮从最老到期行重启，锁内重新核验。','Keep pending+expire_at. Restart the next round at the oldest due row and recheck under lock.'),
 ('收到回调就2xx安全吗？','Can receipt immediately return 2xx?','验签/账户环境类型检查后，完整事件持久入inbox才2xx，worker可恢复。','After signature/scope/type checks, commit the complete inbox before 2xx so workers can recover.'),
 ('outbox投递为何仍重复？','Why can outbox publication duplicate?','broker收了但sent未落库；重发原event，消费inbox与唯一Job同事务。','Broker acceptance can precede sent marking. Resend the same event; inbox and unique Job co-commit.'),
 ('139,200条积压多久排空？','How long to drain 139,200 events?','2,000−1,160=840/s净排空；约166秒，停机120秒另算。','Net drain is 2,000−1,160=840/s: about 166 seconds, plus the 120-second outage.'),
]
flash = ''.join('<button type="button" class="flip"><span class="q"><span class="lang-zh">'+qz+'</span> <span class="lang-en">'+qe+'</span></span><span class="a"><span class="lang-zh">'+az+'</span> <span class="lang-en">'+ae+'</span></span></button>' for qz,qe,az,ae in cards)
flash = section('闪卡', 'Flashcards', '<p class="cite"><span class="lang-zh">先讲提交边界，再讲反例。</span> <span class="lang-en">State the commit boundary, then the counterexample.</span></p><div class="cards-grid">'+flash+'</div>')

